function terminationPhase5ValidatePinnedEnvelope(
  envelope,
  expectedBinding,
  rootKeys,
  idField,
  code,
  label,
) {
  terminationProposalExactKeys(
    envelope.binding,
    ['byte_length', 'path', 'record_id', 'record_id_field', 'schema_version', 'sha256'],
    code,
    `${label} binding`,
  );
  if (!terminationProposalSame(envelope.binding, expectedBinding)) {
    fail(code, `${label} binding drift.`);
  }
  validateBoundRecord(envelope, code, label);
  const { record } = envelope;
  if (
    !terminationPhase4ReviewHasOrderedKeys(record, rootKeys) ||
    record.schema_version !== expectedBinding.schema_version ||
    record[idField] !== expectedBinding.record_id
  ) fail(code, `${label} identity drift.`);
  const unsigned = clone(record);
  delete unsigned[idField];
  if (contentId(record.schema_version, unsigned) !== expectedBinding.record_id) {
    fail(code, `${label} self identity drift.`);
  }
  return deepFreeze(clone(envelope));
}

