function terminationWork3StageAValidatePublicContract(input) {
  const code = TERMINATION_WORK3_STAGE_A_CODES.CONTRACT;
  if (!terminationPhase4ReviewHasOrderedKeys(
    input,
    TERMINATION_WORK3_STAGE_A_INPUT_KEYS,
  )) fail(code, 'Stage A schema compatibility input drift.');
  const evidence = input.terminationWork3SchemaSuccessorEvidence;
  if (!terminationPhase4ReviewHasOrderedKeys(
    evidence,
    TERMINATION_WORK3_STAGE_A_EVIDENCE_KEYS,
  )) fail(code, 'Stage A successor evidence bundle drift.');
  for (const key of TERMINATION_WORK3_STAGE_A_EVIDENCE_KEYS) {
    const envelope = evidence[key];
    if (
      !terminationPhase4ReviewHasOrderedKeys(envelope, ['binding', 'record']) ||
      !terminationProposalIsObject(envelope.binding) ||
      !terminationProposalIsObject(envelope.record)
    ) fail(code, `Stage A ${key} envelope drift.`);
  }
  return evidence;
}

