function terminationWork3StageAValidateDynamicIdBoundary(candidate, dynamicId) {
  const code = TERMINATION_WORK3_STAGE_A_CODES.OUTPUT;
  let exactCount = 0;
  const seen = new Set();
  const visit = (member) => {
    if (typeof member === 'string') {
      if (member === dynamicId) exactCount += 1;
      if (member === `${dynamicId}\n`) {
        fail(code, 'Stage A discarded historical output was copied.');
      }
      return;
    }
    if (!member || typeof member !== 'object' || seen.has(member)) return;
    seen.add(member);
    for (const child of Object.values(member)) visit(child);
  };
  visit(candidate);
  if (
    exactCount !== 1 ||
    candidate.phase5_resolution_reference.resolution_candidate_id !== dynamicId
  ) fail(code, 'Stage A fresh Phase5 candidate identity provenance drift.');
}

