function prepareTerminationWork3StageBBlueprintProposal(input) {
  const code = TERMINATION_WORK3_STAGE_B_CODES.CONTRACT;
  if (!terminationPhase4ReviewHasOrderedKeys(
    input,
    TERMINATION_WORK3_STAGE_A_INPUT_KEYS,
  )) fail(code, 'Stage B blueprint input drift.');

  let stageA;
  try {
    stageA = prepareTerminationGovernedDisclosureNoteWork3SchemaCompatibilityReview(
      input,
    );
  } catch (error) {
    fail(
      TERMINATION_WORK3_STAGE_B_CODES.STAGE_A,
      'Stage B Stage A schema compatibility review failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  let phase5;
  try {
    phase5 = prepareTerminationFamilyProfilePackageResolution(
      input.terminationPhase5ResolutionInput,
    );
  } catch (error) {
    fail(
      TERMINATION_WORK3_STAGE_B_CODES.PHASE5,
      'Stage B Phase5 resolution candidate failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  const proposedProfiles = terminationWork3StageBAttachOutsideDateExtensionLinks(
    clone(phase5.proposed_profiles),
  );
  terminationWork3StageBValidateOutsideDateExtensionLinks(proposedProfiles);
  const retainedGaps = clone(phase5.retained_source_gaps);
  const incompleteProfileCount = retainedGaps.length;
  const proposedProfileCount = proposedProfiles.length;
  const completeProfileCount = proposedProfileCount - incompleteProfileCount;
  const b9e = proposedProfiles.find((profile) => (
    profile.proposed_profile_key === TERMINATION_WORK3_STAGE_B_B9E_PROFILE_KEY
  ));
  const outputCode = TERMINATION_WORK3_STAGE_B_CODES.OUTPUT;
  if (
    proposedProfileCount !== 45 ||
    completeProfileCount !== 44 ||
    incompleteProfileCount !== 1 ||
    !b9e ||
    !Array.isArray(b9e.governed_disclosure_notes) ||
    b9e.governed_disclosure_notes.length !== 1 ||
    b9e.governed_disclosure_notes[0].display_text !==
      'contained in non-public disclosure letter' ||
    b9e.governed_disclosure_notes[0].disposition_kind !==
      'NON_PUBLIC_DISCLOSURE_LOCATION'
  ) fail(outputCode, 'Stage B 45-profile blueprint census drift.');

  const unsigned = {
    schema_version: TERMINATION_WORK3_STAGE_B_SCHEMA,
    candidate_state:
      'UNAPPROVED_45_PROFILE_BLUEPRINT_PROPOSAL_NO_WORK3_IDENTITY_OR_CORE_INTEGRATION',
    profile_approval_state: 'UNAPPROVED',
    proposed_profile_count: proposedProfileCount,
    complete_profile_count: completeProfileCount,
    incomplete_profile_count: incompleteProfileCount,
    stage_a_reference: {
      schema_compatibility_review_id: stageA.schema_compatibility_review_id,
      candidate_state: stageA.candidate_state,
    },
    proposed_profiles: proposedProfiles,
    review_accounting: {
      proposed_profile_count: proposedProfileCount,
      complete_profile_count: completeProfileCount,
      incomplete_profile_count: incompleteProfileCount,
      core_integration_count: 0,
      work3_identity_count: 0,
      approval_count: 0,
      retained_source_gap_count: incompleteProfileCount,
      state:
        'UNAPPROVED_45_PROFILE_BLUEPRINT_PROPOSAL_44_COMPLETE_ONE_RETAINED_SOURCE_GAP',
    },
    retained_source_gaps: retainedGaps,
    withheld_work3_fields: clone(TERMINATION_WORK3_STAGE_B_WITHHELD_FIELDS),
    next_governance_stop: terminationWork3StageBExpectedNextStop(),
    zero_effect_boundary: terminationWork3StageAExpectedZeroBoundary(),
  };
  const result = {
    schema_version: unsigned.schema_version,
    blueprint_proposal_id: contentId(unsigned.schema_version, unsigned),
    candidate_state: unsigned.candidate_state,
    profile_approval_state: unsigned.profile_approval_state,
    proposed_profile_count: unsigned.proposed_profile_count,
    complete_profile_count: unsigned.complete_profile_count,
    incomplete_profile_count: unsigned.incomplete_profile_count,
    stage_a_reference: unsigned.stage_a_reference,
    proposed_profiles: unsigned.proposed_profiles,
    review_accounting: unsigned.review_accounting,
    retained_source_gaps: unsigned.retained_source_gaps,
    withheld_work3_fields: unsigned.withheld_work3_fields,
    next_governance_stop: unsigned.next_governance_stop,
    zero_effect_boundary: unsigned.zero_effect_boundary,
  };
  if (
    !terminationPhase4ReviewHasOrderedKeys(
      result,
      TERMINATION_WORK3_STAGE_B_RESULT_KEYS,
    ) ||
    terminationPhase4ReviewContainsForbiddenKey(
      result,
      new Set(TERMINATION_WORK3_STAGE_B_WITHHELD_FIELDS),
    )
  ) fail(outputCode, 'Stage B blueprint identity or key-order drift.');
  const frozen = deepFreeze(clone(result));
  if (!terminationPhase4ReviewIsDeepFrozen(frozen)) {
    fail(outputCode, 'Stage B blueprint proposal is not deeply frozen.');
  }
  return frozen;
}

