function terminationWork3CoreBuildCompileProof(note) {
  const sourceText = 'anchor and note';
  const anchorStart = 0;
  const andStart = sourceText.indexOf('and');
  const noteStart = sourceText.indexOf('note');
  const source = {
    text: sourceText,
    facts: [{
      field_key: 'ANCHOR_FACT',
      value_type: 'ENUM',
      typed_value: 'ANCHOR',
      legal_subject: 'COMPANY',
      selector: {
        start_byte: anchorStart,
        end_byte: anchorStart + Buffer.byteLength('anchor', 'utf8'),
        quote: 'anchor',
      },
    }],
    governed_disclosure_notes: [note],
    expression: {
      operator: 'ALL_OF',
      selector: {
        start_byte: andStart,
        end_byte: andStart + Buffer.byteLength('and', 'utf8'),
        quote: 'and',
      },
      children: [
        { fact_key: 'ANCHOR_FACT' },
        { governed_disclosure_note_id: note.governed_disclosure_note_id },
      ],
    },
  };
  return compileSyntheticProfileExpression({
    agreement_id: note.agreement_id,
    agreement_index_id: 'core-integration-fixture-index',
    source_node_occurrence_id: 'core-integration-fixture-node',
    profile: {
      profile_id: 'core-integration-fixture-profile',
      allowed_operators: ['ALL_OF'],
      required_expression_signature:
        `ALL_OF(ANCHOR_FACT,${note.field_key})`,
    },
    source,
  });
}

