function prepareTerminationWork3UnapprovedInventoryReview(input) {
  const evidence = terminationWork3InventoryValidatePublicContract(input);
  const authorityEnvelope = terminationWork3InventoryValidateAuthority(
    evidence.work3TerminationUnapprovedInventoryReviewAuthority,
  );
  terminationWork3CoreValidateAuthority(
    evidence.work3GovernedDisclosureNoteCoreIntegrationAuthority,
  );
  terminationWork3StageAValidateAuthority(
    evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
  );
  terminationWork3StageAValidateWork3Authority(
    evidence.work3EntryCorrectionAuthority,
    terminationWork3StageAValidateAuthority(
      evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
    ),
  );
  terminationWork3StageAValidateCompletion(
    evidence.phase5ExecutionCompletionReceipt,
    terminationWork3StageAValidateAuthority(
      evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
    ),
  );
  terminationWork3StageAValidatePhase5Input(input.terminationPhase5ResolutionInput);

  const coreIntegrationInput = {
    terminationWork3CoreIntegrationEvidence: {
      work3EntryCorrectionAuthority: evidence.work3EntryCorrectionAuthority,
      phase5ExecutionCompletionReceipt: evidence.phase5ExecutionCompletionReceipt,
      work3GovernedDisclosureNoteSchemaSuccessorAuthority:
        evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
      work3GovernedDisclosureNoteCoreIntegrationAuthority:
        evidence.work3GovernedDisclosureNoteCoreIntegrationAuthority,
    },
    terminationPhase5ResolutionInput: input.terminationPhase5ResolutionInput,
  };

  let coreIntegration;
  try {
    coreIntegration = prepareTerminationGovernedDisclosureNoteWork3CoreIntegrationReview(
      coreIntegrationInput,
    );
  } catch (error) {
    fail(
      TERMINATION_WORK3_INVENTORY_CODES.CORE,
      'Work3 termination unapproved inventory review core integration derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  let stageB;
  try {
    stageB = prepareTerminationWork3StageBBlueprintProposal({
      terminationWork3SchemaSuccessorEvidence: {
        work3EntryCorrectionAuthority: evidence.work3EntryCorrectionAuthority,
        phase5ExecutionCompletionReceipt: evidence.phase5ExecutionCompletionReceipt,
        work3GovernedDisclosureNoteSchemaSuccessorAuthority:
          evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
      },
      terminationPhase5ResolutionInput: input.terminationPhase5ResolutionInput,
    });
  } catch (error) {
    fail(
      TERMINATION_WORK3_INVENTORY_CODES.STAGE_B,
      'Work3 termination unapproved inventory review Stage B blueprint derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  let validatorAcceptance;
  try {
    validatorAcceptance = validateTerminationUnapprovedInventoryReviewEvidence({
      profile_approval_state: stageB.profile_approval_state,
      profile_count: stageB.proposed_profile_count,
      complete_profile_count: stageB.complete_profile_count,
      incomplete_profile_count: stageB.incomplete_profile_count,
      proposed_profiles: stageB.proposed_profiles,
      retained_source_gaps: stageB.retained_source_gaps,
    });
  } catch (error) {
    fail(
      TERMINATION_WORK3_INVENTORY_CODES.VALIDATOR,
      'Work3 termination unapproved inventory review validator acceptance failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  try {
    const result = deepFreeze(clone(terminationWork3InventoryBuildCandidate(
      authorityEnvelope,
      coreIntegration,
      stageB,
      validatorAcceptance,
    )));
    terminationWork3InventoryValidateOutput(result);
    return result;
  } catch (error) {
    if (
      error instanceof M7V2ProfileAuthoringError &&
      error.code === TERMINATION_WORK3_INVENTORY_CODES.OUTPUT
    ) throw error;
    fail(
      TERMINATION_WORK3_INVENTORY_CODES.OUTPUT,
      'Work3 termination unapproved inventory review candidate derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }
}

