function terminationWork3BenInventoryValidatePublicContract(input) {
  const code = TERMINATION_WORK3_BEN_INVENTORY_CODES.CONTRACT;
  if (!terminationPhase4ReviewHasOrderedKeys(
    input,
    TERMINATION_WORK3_BEN_INVENTORY_INPUT_KEYS,
  )) fail(code, 'Work3 termination Ben inventory session disposition input drift.');
  const evidence = input.terminationWork3BenInventorySessionDispositionEvidence;
  if (!terminationPhase4ReviewHasOrderedKeys(
    evidence,
    TERMINATION_WORK3_BEN_INVENTORY_EVIDENCE_KEYS,
  )) fail(code, 'Work3 termination Ben inventory session disposition evidence bundle drift.');
  for (const key of TERMINATION_WORK3_BEN_INVENTORY_EVIDENCE_KEYS) {
    const envelope = evidence[key];
    if (
      !terminationPhase4ReviewHasOrderedKeys(envelope, ['binding', 'record']) ||
      !terminationProposalIsObject(envelope.binding) ||
      !terminationProposalIsObject(envelope.record)
    ) fail(code, `Work3 termination Ben inventory session disposition ${key} envelope drift.`);
  }
  return evidence;
}

function terminationWork3BenInventoryValidateDispositionRow(row) {
  const code = TERMINATION_WORK3_BEN_INVENTORY_CODES.DISPOSITION;
  if (!terminationProposalIsObject(row)) {
    fail(code, 'Work3 termination Ben inventory disposition row drift.');
  }
  const keys = Object.keys(row);
  const baseKeys = [...TERMINATION_WORK3_BEN_INVENTORY_DISPOSITION_ROW_KEYS];
  if (row.disposition_reason !== undefined) baseKeys.push('disposition_reason');
  if (row.no_extension_complete !== undefined) baseKeys.push('no_extension_complete');
  if (!terminationProposalSame(keys.sort(), baseKeys.sort())) {
    fail(code, 'Work3 termination Ben inventory disposition row shape drift.');
  }
  if (
    typeof row.proposed_profile_key !== 'string' ||
    !Number.isInteger(row.ordinal) ||
  row.ordinal < 1 ||
    !['APPROVE', 'HOLD', 'REJECT', 'PARTIAL_APPROVE'].includes(row.disposition) ||
    !Array.isArray(row.review_flags_acknowledged) ||
    typeof row.extension_deferred_acknowledged !== 'boolean' ||
    (row.no_extension_complete !== undefined &&
      typeof row.no_extension_complete !== 'boolean')
  ) fail(code, 'Work3 termination Ben inventory disposition row value drift.');
}

function terminationWork3BenInventoryValidateDispositionEnvelope(
  envelope,
  packetBinding,
  rulingsBinding,
) {
  const code = TERMINATION_WORK3_BEN_INVENTORY_CODES.DISPOSITION;
  const record = envelope.record;
  const binding = envelope.binding;
  const canonicalText = canonicalJson(record);
  const canonicalBytes = Buffer.from(canonicalText, 'utf8');
  if (
    binding.path !== TERMINATION_WORK3_BEN_INVENTORY_DISPOSITION_PATH ||
    binding.schema_version !== TERMINATION_WORK3_BEN_INVENTORY_DISPOSITION_SCHEMA ||
    binding.record_id_field !== 'inventory_disposition_id' ||
    binding.byte_length !== canonicalBytes.length ||
    binding.sha256 !== sha256Hex(canonicalBytes) ||
    binding.record_id !== record.inventory_disposition_id
  ) {
    fail(code, 'Ben-authored inventory disposition binding drift.');
  }
  if (
    !terminationPhase4ReviewHasOrderedKeys(
      record,
      TERMINATION_WORK3_BEN_INVENTORY_DISPOSITION_RECORD_KEYS,
    ) ||
    record.schema_version !== TERMINATION_WORK3_BEN_INVENTORY_DISPOSITION_SCHEMA ||
    record.packet_digest !== packetBinding.sha256 ||
    record.ben_rulings_digest !== rulingsBinding.sha256 ||
    record.reviewer !== 'BEN_GOODCHILD' ||
    record.default_disposition_applied !== true ||
    !Array.isArray(record.profile_dispositions) ||
    record.profile_dispositions.length !== 45
  ) fail(code, 'Work3 termination Ben inventory disposition record drift.');
  const unsigned = clone(record);
  delete unsigned.inventory_disposition_id;
  delete unsigned.session_receipt_id;
  if (
    contentId(record.schema_version, unsigned) !== record.inventory_disposition_id ||
    envelope.binding.record_id !== record.inventory_disposition_id ||
    envelope.binding.record_id_field !== 'inventory_disposition_id' ||
    envelope.binding.schema_version !== record.schema_version
  ) fail(code, 'Work3 termination Ben inventory disposition identity drift.');
  for (const row of record.profile_dispositions) {
    terminationWork3BenInventoryValidateDispositionRow(row);
  }
  const summary = record.session_summary;
  if (
    !terminationProposalIsObject(summary) ||
    !Number.isInteger(summary.approved_count) ||
    !Number.isInteger(summary.hold_count) ||
    !Number.isInteger(summary.reject_count) ||
    !Number.isInteger(summary.partial_count) ||
    !Number.isInteger(summary.outside_date_hold_count) ||
    summary.b9e_note_only_acknowledged !== true ||
    summary.taxonomy_expansion_acknowledged !== true
  ) fail(code, 'Work3 termination Ben inventory disposition session summary drift.');
  return record;
}

