function prepareTerminationWork3BenInventorySessionDisposition(input) {
  const evidence = terminationWork3BenInventoryValidatePublicContract(input);
  const authorityEnvelope = terminationWork3BenInventoryValidateAuthority(
    evidence.work3BenInventorySessionSuccessorAuthority,
  );
  terminationWork3InventoryValidateAuthority(
    evidence.work3TerminationUnapprovedInventoryReviewAuthority,
  );
  terminationWork3CoreValidateAuthority(
    evidence.work3GovernedDisclosureNoteCoreIntegrationAuthority,
  );
  terminationWork3StageAValidateAuthority(
    evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
  );
  terminationWork3StageAValidateWork3Authority(
    evidence.work3EntryCorrectionAuthority,
    terminationWork3StageAValidateAuthority(
      evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
    ),
  );
  terminationWork3StageAValidateCompletion(
    evidence.phase5ExecutionCompletionReceipt,
    terminationWork3StageAValidateAuthority(
      evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
    ),
  );

  const packetBinding = terminationWork3BenInventoryPacketDraftBinding();
  terminationProposalExactKeys(
    evidence.inventoryReviewPacketDraft.binding,
    ['byte_length', 'path', 'record_id', 'record_id_field', 'schema_version', 'sha256'],
    TERMINATION_WORK3_BEN_INVENTORY_CODES.PACKET,
    'Work3 termination Ben inventory review packet draft binding',
  );
  if (!terminationProposalSame(
    evidence.inventoryReviewPacketDraft.binding,
    packetBinding,
  )) {
    fail(
      TERMINATION_WORK3_BEN_INVENTORY_CODES.PACKET,
      'Work3 termination Ben inventory review packet draft binding drift.',
    );
  }
  const packetRecord = evidence.inventoryReviewPacketDraft.record;
  if (
    packetRecord.schema_version !== packetBinding.schema_version ||
    packetRecord.inventory_review_packet_id !== packetBinding.record_id
  ) {
    fail(
      TERMINATION_WORK3_BEN_INVENTORY_CODES.PACKET,
      'Work3 termination Ben inventory review packet draft identity drift.',
    );
  }

  const rulingsBinding = terminationWork3BenInventoryRulingsNoteBinding();
  const dispositionRecord = terminationWork3BenInventoryValidateDispositionEnvelope(
    evidence.benAuthoredInventoryDisposition,
    packetBinding,
    rulingsBinding,
  );

  const inventoryInput = {
    terminationWork3UnapprovedInventoryReviewEvidence: {
      work3EntryCorrectionAuthority: evidence.work3EntryCorrectionAuthority,
      phase5ExecutionCompletionReceipt: evidence.phase5ExecutionCompletionReceipt,
      work3GovernedDisclosureNoteSchemaSuccessorAuthority:
        evidence.work3GovernedDisclosureNoteSchemaSuccessorAuthority,
      work3GovernedDisclosureNoteCoreIntegrationAuthority:
        evidence.work3GovernedDisclosureNoteCoreIntegrationAuthority,
      work3TerminationUnapprovedInventoryReviewAuthority:
        evidence.work3TerminationUnapprovedInventoryReviewAuthority,
    },
    terminationPhase5ResolutionInput: input.terminationPhase5ResolutionInput,
  };

  let inventoryReview;
  try {
    inventoryReview = prepareTerminationWork3UnapprovedInventoryReview(inventoryInput);
  } catch (error) {
    fail(
      TERMINATION_WORK3_BEN_INVENTORY_CODES.INVENTORY,
      'Work3 termination Ben inventory session disposition inventory review derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  try {
    validateTerminationUnapprovedInventoryReviewEvidence({
      profile_approval_state: 'UNAPPROVED',
      profile_count: 45,
      complete_profile_count: 44,
      incomplete_profile_count: 1,
      proposed_profiles: dispositionRecord.profile_dispositions.map((row) => ({
        proposed_profile_key: row.proposed_profile_key,
      })),
      retained_source_gaps: [{ retained_source_gap: true }],
    });
  } catch (error) {
    fail(
      TERMINATION_WORK3_BEN_INVENTORY_CODES.INVENTORY,
      'Work3 termination Ben inventory session disposition validator acceptance failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  try {
    const result = deepFreeze(clone(terminationWork3BenInventoryBuildCandidate(
      authorityEnvelope,
      inventoryReview,
      dispositionRecord,
      packetBinding,
      rulingsBinding,
    )));
    terminationWork3BenInventoryValidateOutput(result);
    return result;
  } catch (error) {
    if (
      error instanceof M7V2ProfileAuthoringError &&
      error.code === TERMINATION_WORK3_BEN_INVENTORY_CODES.OUTPUT
    ) throw error;
    fail(
      TERMINATION_WORK3_BEN_INVENTORY_CODES.OUTPUT,
      'Work3 termination Ben inventory session disposition candidate derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }
}

