function terminationWork3RegistrationValidateAuthority(envelope) {
  const code = TERMINATION_WORK3_REGISTRATION_CODES.AUTHORITY;
  const binding = terminationWork3RegistrationAuthorityBinding(
    TERMINATION_WORK3_REGISTRATION_AUTHORITY_ID,
    TERMINATION_WORK3_REGISTRATION_AUTHORITY_BYTES,
    TERMINATION_WORK3_REGISTRATION_AUTHORITY_SHA256,
  );
  const validated = terminationPhase5ValidatePinnedEnvelope(
    envelope,
    binding,
    TERMINATION_WORK3_REGISTRATION_AUTHORITY_ROOT_KEYS,
    'work3_termination_registration_successor_authority_id',
    code,
    'Work3 termination registration successor authority',
  );
  const authority = validated.record;
  const candidate = authority.schema_review_candidate_contract;
  const implementation = authority.implementation_contract;
  const registration = authority.permitted_write_contract;
  if (
    authority.authority_classification !== TERMINATION_WORK3_REGISTRATION_CLASSIFICATION ||
    authority.authority_state !==
      'AUTHORISED_FAMILY_PACKAGE_REGISTRATION_ONLY_ZERO_PRODUCT_WRITE_EFFECT' ||
    candidate.schema_version !== TERMINATION_WORK3_REGISTRATION_CANDIDATE_SCHEMA ||
    candidate.candidate_state !==
      'BEN_TERMINATION_FAMILY_PACKAGE_REGISTERED_ZERO_PRODUCT_WRITE_EFFECT' ||
    implementation.exported_function !==
      'prepareTerminationWork3FamilyPackageRegistration' ||
    implementation.caller_produced_registration_forbidden !== true ||
    registration.registration_step_permitted !== true ||
    registration.work3_identity_emission_permitted !== true ||
    registration.repository_write_permitted !== false ||
    !terminationProposalSame(
      implementation.exact_outer_input_keys,
      TERMINATION_WORK3_REGISTRATION_INPUT_KEYS,
    ) ||
    !terminationProposalSame(
      implementation.exact_successor_evidence_keys,
      TERMINATION_WORK3_REGISTRATION_EVIDENCE_KEYS,
    ) ||
    !terminationProposalSame(
      candidate.review_accounting_exact_values,
      terminationWork3RegistrationExpectedAccounting(),
    ) ||
    !terminationProposalSame(
      candidate.next_governance_stop_contract,
      terminationWork3RegistrationExpectedNextStop(),
    ) ||
    !terminationProposalSame(
      candidate.zero_effect_boundary_rule,
      'EQUALS_AUTHORITY_ZERO_EFFECT_BOUNDARY',
    )
  ) fail(code, 'Work3 termination registration successor authority contract drift.');
  return validated;
}

function terminationWork3RegistrationValidatePublicContract(input) {
  const code = TERMINATION_WORK3_REGISTRATION_CODES.CONTRACT;
  if (!terminationPhase4ReviewHasOrderedKeys(
    input,
    TERMINATION_WORK3_REGISTRATION_INPUT_KEYS,
  )) fail(code, 'Work3 termination family package registration input drift.');
  const evidence = input.terminationWork3FamilyPackageRegistrationEvidence;
  if (!terminationPhase4ReviewHasOrderedKeys(
    evidence,
    TERMINATION_WORK3_REGISTRATION_EVIDENCE_KEYS,
  )) fail(code, 'Work3 termination family package registration evidence drift.');
  for (const key of TERMINATION_WORK3_REGISTRATION_EVIDENCE_KEYS) {
    const envelope = evidence[key];
    if (
      !terminationPhase4ReviewHasOrderedKeys(envelope, ['binding', 'record']) ||
      !terminationProposalIsObject(envelope.binding) ||
      !terminationProposalIsObject(envelope.record)
    ) fail(code, `Work3 termination family package registration ${key} envelope drift.`);
  }
  terminationWork3StageAValidatePhase5Input(input.terminationPhase5ResolutionInput);
  return evidence;
}

function terminationWork3RegistrationValidateSealReceiptEnvelope(envelope) {
  const code = TERMINATION_WORK3_REGISTRATION_CODES.SEAL_RECEIPT;
  const expectedBinding = terminationWork3RegistrationSealReceiptBinding();
  terminationProposalExactKeys(
    envelope.binding,
    ['byte_length', 'path', 'record_id', 'record_id_field', 'schema_version', 'sha256'],
    code,
    'Work3 termination family package registration seal receipt envelope binding',
  );
  if (!terminationProposalSame(envelope.binding, expectedBinding)) {
    fail(code, 'Work3 termination family package registration seal receipt binding drift.');
  }
  const record = envelope.record;
  if (
    !terminationPhase4ReviewHasOrderedKeys(
      record,
      TERMINATION_WORK3_REGISTRATION_SEAL_RECEIPT_RECORD_KEYS,
    ) ||
    record.schema_version !== TERMINATION_WORK3_REGISTRATION_SEAL_RECEIPT_SCHEMA ||
    record.completion_state !== 'COMPLETE' ||
    record.seal_classification !== 'TERMINATION_WORK3_FAMILY_PACKAGE_SEAL' ||
    record.reviewer !== 'BEN_GOODCHILD' ||
    record.termination_family_package_seal_receipt_id !==
      TERMINATION_WORK3_REGISTRATION_SEAL_RECEIPT_ID ||
    record.disposition_binding.inventory_disposition_id !==
      TERMINATION_WORK3_FAMILY_PACKAGE_SEAL_DISPOSITION_ID ||
    record.next_governance_stop.package_seal_state !== 'RECORDED' ||
    record.next_governance_stop.registration_permitted !== false ||
    record.zero_effect_boundary.package_registration_count !== 0 ||
    record.zero_effect_boundary.product_write_count !== 0 ||
    record.zero_effect_boundary.work3_identity_count !== 0
  ) fail(code, 'Work3 termination family package registration seal receipt identity drift.');
  return record;
}

