function prepareMaeDefinitionWork3UnapprovedInventoryReview(input) {
  const contractCode = MAE_WORK3_INVENTORY_CODES.CONTRACT;
  if (!maeWork3HasOrderedKeys(input, MAE_WORK3_INVENTORY_INPUT_KEYS)) {
    fail(contractCode, 'MAE Work3 unapproved inventory review input drift.');
  }
  const authorityEnvelope = maeWork3ValidatePinnedEnvelope(
    input.maeDefinitionWork3UnapprovedInventoryReviewEvidence
      .work3MaeDefinitionUnapprovedInventoryReviewAuthority,
    maeWork3PhysicalBinding(
      MAE_WORK3_INVENTORY_AUTHORITY_BYTES,
      MAE_WORK3_INVENTORY_AUTHORITY_PATH,
      MAE_WORK3_INVENTORY_AUTHORITY_ID,
      'work3_mae_definition_unapproved_inventory_review_authority_id',
      MAE_WORK3_INVENTORY_AUTHORITY_SCHEMA,
      MAE_WORK3_INVENTORY_AUTHORITY_SHA256,
    ),
    'work3_mae_definition_unapproved_inventory_review_authority_id',
    MAE_WORK3_INVENTORY_CODES.AUTHORITY,
    'MAE Work3 unapproved inventory review authority',
  );
  maeWork3ValidatePhase4ReviewInput(input.maeDefinitionPhase4ReviewInput);

  let phase4Review;
  try {
    phase4Review = prepareMaeDefinitionFamilyProfilePackageReview(
      input.maeDefinitionPhase4ReviewInput,
    );
  } catch (error) {
    fail(
      MAE_WORK3_INVENTORY_CODES.PHASE4,
      'MAE Work3 unapproved inventory review Phase4 derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  const packetBinding = maeWork3InventoryPacketDraftBinding();
  const authority = authorityEnvelope.record;
  const contract = authority.schema_review_candidate_contract;
  const unsigned = {
    candidate_state: contract.candidate_state,
    authority_binding: maeWork3AuthorityBinding(authorityEnvelope),
    phase4_review_reference: {
      review_candidate_id: phase4Review.review_candidate_id,
      derived_profile_count: phase4Review.phase2_proposal_reference.derived_profile_count,
    },
    inventory_review_packet_binding: clone(packetBinding),
    review_accounting: clone(contract.review_accounting_exact_values),
    withheld_work3_fields: clone(MAE_WORK3_WITHHELD_FIELDS),
    zero_effect_boundary: clone(authority.zero_effect_boundary),
  };
  const candidate = {
    schema_version: MAE_WORK3_INVENTORY_CANDIDATE_SCHEMA,
    inventory_review_candidate_id: contentId(
      MAE_WORK3_INVENTORY_CANDIDATE_SCHEMA,
      unsigned,
    ),
    ...unsigned,
  };
  if (
    !exactKeys(candidate, MAE_WORK3_INVENTORY_CANDIDATE_KEYS) ||
    candidate.review_accounting.profile_proposal_count !== 4
  ) {
    fail(MAE_WORK3_INVENTORY_CODES.OUTPUT, 'MAE Work3 unapproved inventory review output drift.');
  }
  return deepFreeze(clone(candidate));
}

function prepareMaeDefinitionWork3BenInventorySessionDisposition(input) {
  const contractCode = MAE_WORK3_BEN_INVENTORY_CODES.CONTRACT;
  if (!maeWork3HasOrderedKeys(input, MAE_WORK3_BEN_INVENTORY_INPUT_KEYS)) {
    fail(contractCode, 'MAE Work3 ben inventory session disposition input drift.');
  }
  const evidence = input.maeDefinitionWork3BenInventorySessionDispositionEvidence;
  const authorityEnvelope = maeWork3ValidatePinnedEnvelope(
    evidence.work3MaeDefinitionBenInventorySessionSuccessorAuthority,
    maeWork3PhysicalBinding(
      MAE_WORK3_BEN_INVENTORY_AUTHORITY_BYTES,
      MAE_WORK3_BEN_INVENTORY_AUTHORITY_PATH,
      MAE_WORK3_BEN_INVENTORY_AUTHORITY_ID,
      'work3_mae_definition_ben_inventory_session_successor_authority_id',
      MAE_WORK3_BEN_INVENTORY_AUTHORITY_SCHEMA,
      MAE_WORK3_BEN_INVENTORY_AUTHORITY_SHA256,
    ),
    'work3_mae_definition_ben_inventory_session_successor_authority_id',
    MAE_WORK3_BEN_INVENTORY_CODES.AUTHORITY,
    'MAE Work3 ben inventory session successor authority',
  );
  maeWork3ValidatePhase4ReviewInput(input.maeDefinitionPhase4ReviewInput);
  const packetBinding = maeWork3InventoryPacketDraftBinding();
  maeWork3ValidateInventoryPacketEnvelope(evidence.inventoryReviewPacketDraft);
  const dispositionRecord = maeWork3ValidateDispositionEnvelope(
    evidence.benAuthoredInventoryDisposition,
    packetBinding,
  );

  const authority = authorityEnvelope.record;
  const contract = authority.schema_review_candidate_contract;
  const unsigned = {
    candidate_state: contract.candidate_state,
    authority_binding: maeWork3AuthorityBinding(authorityEnvelope),
    inventory_review_packet_binding: clone(packetBinding),
    disposition_binding: {
      path: MAE_WORK3_BEN_INVENTORY_DISPOSITION_PATH,
      inventory_disposition_id: dispositionRecord.inventory_disposition_id,
      packet_digest: dispositionRecord.packet_digest,
      ben_rulings_digest: dispositionRecord.ben_rulings_digest,
      profile_disposition_count: dispositionRecord.profile_dispositions.length,
      session_summary: clone(dispositionRecord.session_summary),
    },
    review_accounting: clone(contract.review_accounting_exact_values),
    withheld_work3_fields: clone(MAE_WORK3_WITHHELD_FIELDS),
    next_governance_stop: {
      state: 'STOP_AFTER_BEN_INVENTORY_DISPOSITION_BEFORE_FAMILY_PACKAGE_SEAL',
      package_seal_state: 'NOT_RECORDED',
    },
    zero_effect_boundary: clone(authority.zero_effect_boundary),
  };
  const candidate = {
    schema_version: MAE_WORK3_BEN_INVENTORY_CANDIDATE_SCHEMA,
    inventory_session_disposition_id: contentId(
      MAE_WORK3_BEN_INVENTORY_CANDIDATE_SCHEMA,
      unsigned,
    ),
    ...unsigned,
  };
  if (
    !exactKeys(candidate, MAE_WORK3_BEN_INVENTORY_CANDIDATE_KEYS) ||
    candidate.review_accounting.approved_count !== 4
  ) {
    fail(MAE_WORK3_BEN_INVENTORY_CODES.OUTPUT, 'MAE Work3 ben inventory disposition output drift.');
  }
  return deepFreeze(clone(candidate));
}

function prepareMaeDefinitionWork3FamilyPackageSeal(input) {
  const contractCode = MAE_WORK3_FAMILY_PACKAGE_SEAL_CODES.CONTRACT;
  if (!maeWork3HasOrderedKeys(input, MAE_WORK3_FAMILY_PACKAGE_SEAL_INPUT_KEYS)) {
    fail(contractCode, 'MAE Work3 family package seal input drift.');
  }
  const evidence = input.maeDefinitionWork3FamilyPackageSealEvidence;
  const authorityEnvelope = maeWork3ValidatePinnedEnvelope(
    evidence.work3MaeDefinitionFamilyPackageSealSuccessorAuthority,
    maeWork3PhysicalBinding(
      MAE_WORK3_FAMILY_PACKAGE_SEAL_AUTHORITY_BYTES,
      MAE_WORK3_FAMILY_PACKAGE_SEAL_AUTHORITY_PATH,
      MAE_WORK3_FAMILY_PACKAGE_SEAL_AUTHORITY_ID,
      'work3_mae_definition_family_package_seal_successor_authority_id',
      MAE_WORK3_FAMILY_PACKAGE_SEAL_AUTHORITY_SCHEMA,
      MAE_WORK3_FAMILY_PACKAGE_SEAL_AUTHORITY_SHA256,
    ),
    'work3_mae_definition_family_package_seal_successor_authority_id',
    MAE_WORK3_FAMILY_PACKAGE_SEAL_CODES.AUTHORITY,
    'MAE Work3 family package seal successor authority',
  );
  maeWork3ValidatePhase4ReviewInput(input.maeDefinitionPhase4ReviewInput);
  const packetBinding = maeWork3InventoryPacketDraftBinding();
  const dispositionRecord = maeWork3ValidateDispositionEnvelope(
    evidence.benAuthoredInventoryDisposition,
    packetBinding,
  );
  const sessionReceiptRecord = maeWork3ValidateSessionReceiptEnvelope(
    evidence.benInventorySessionReceipt,
    dispositionRecord.inventory_disposition_id,
  );

  const inventoryInput = {
    maeDefinitionWork3BenInventorySessionDispositionEvidence: {
      work3MaeDefinitionBenInventorySessionSuccessorAuthority:
        evidence.work3MaeDefinitionBenInventorySessionSuccessorAuthority,
      inventoryReviewPacketDraft: evidence.inventoryReviewPacketDraft,
      benAuthoredInventoryDisposition: evidence.benAuthoredInventoryDisposition,
    },
    maeDefinitionPhase4ReviewInput: input.maeDefinitionPhase4ReviewInput,
  };
  let inventorySessionDisposition;
  try {
    inventorySessionDisposition =
      prepareMaeDefinitionWork3BenInventorySessionDisposition(inventoryInput);
  } catch (error) {
    fail(
      MAE_WORK3_FAMILY_PACKAGE_SEAL_CODES.DISPOSITION,
      'MAE Work3 family package seal inventory session disposition derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  const authority = authorityEnvelope.record;
  const contract = authority.schema_review_candidate_contract;
  const rulingsBinding = {
    path: MAE_WORK3_BEN_INVENTORY_RULINGS_NOTE_PATH,
    sha256: MAE_WORK3_BEN_INVENTORY_RULINGS_NOTE_SHA256,
    byte_length: 3804,
  };
  const reviewStampsBinding = {
    ...rulingsBinding,
    self_containment_status: 'UNPROVEN_ACKNOWLEDGED',
    subject_term_mismatch_status: 'FLAGGED_ACKNOWLEDGED',
  };
  const dispositionBinding = maeWork3PhysicalBinding(
    MAE_WORK3_BEN_INVENTORY_DISPOSITION_BYTES,
    MAE_WORK3_BEN_INVENTORY_DISPOSITION_PATH,
    MAE_WORK3_BEN_INVENTORY_DISPOSITION_ID,
    'inventory_disposition_id',
    MAE_WORK3_BEN_INVENTORY_DISPOSITION_SCHEMA,
    MAE_WORK3_BEN_INVENTORY_DISPOSITION_SHA256,
  );
  const sessionBinding = maeWork3PhysicalBinding(
    MAE_WORK3_BEN_INVENTORY_SESSION_RECEIPT_BYTES,
    MAE_WORK3_BEN_INVENTORY_SESSION_RECEIPT_PATH,
    MAE_WORK3_BEN_INVENTORY_SESSION_RECEIPT_ID,
    'ben_inventory_session_receipt_id',
    MAE_WORK3_BEN_INVENTORY_SESSION_RECEIPT_SCHEMA,
    MAE_WORK3_BEN_INVENTORY_SESSION_RECEIPT_SHA256,
  );
  const unsigned = {
    candidate_state: contract.candidate_state,
    authority_binding: maeWork3AuthorityBinding(authorityEnvelope),
    inventory_session_disposition_reference: {
      inventory_disposition_id: dispositionRecord.inventory_disposition_id,
      candidate_state:
        'BEN_4_PROFILE_INVENTORY_DISPOSITION_CAPTURED_PACKAGE_SEAL_NOT_RECORDED',
    },
    ben_rulings_binding: clone(rulingsBinding),
    disposition_binding: clone(dispositionBinding),
    session_receipt_binding: clone(sessionBinding),
    review_stamps_binding: clone(reviewStampsBinding),
    review_accounting: clone(contract.review_accounting_exact_values),
    withheld_work3_fields: [
      'activation_id',
      'family_profile_package_id',
      'profile_id',
      'registration_id',
    ],
    next_governance_stop: {
      state: 'STOP_AFTER_FAMILY_PACKAGE_SEAL_CAPTURE_BEFORE_REGISTRATION',
      package_seal_state: 'CAPTURED',
      registration_permitted: false,
    },
    zero_effect_boundary: clone(authority.zero_effect_boundary),
  };
  const candidate = {
    schema_version: MAE_WORK3_FAMILY_PACKAGE_SEAL_CANDIDATE_SCHEMA,
    family_package_seal_id: contentId(
      MAE_WORK3_FAMILY_PACKAGE_SEAL_CANDIDATE_SCHEMA,
      {
        schema_version: MAE_WORK3_FAMILY_PACKAGE_SEAL_CANDIDATE_SCHEMA,
        ...unsigned,
      },
    ),
    ...unsigned,
  };
  if (
    !exactKeys(candidate, MAE_WORK3_FAMILY_PACKAGE_SEAL_CANDIDATE_KEYS) ||
    candidate.family_package_seal_id !== MAE_WORK3_FAMILY_PACKAGE_SEAL_ID ||
    candidate.review_accounting.profile_disposition_count !== 4
  ) {
    fail(MAE_WORK3_FAMILY_PACKAGE_SEAL_CODES.OUTPUT, 'MAE Work3 family package seal output drift.');
  }
  return deepFreeze(clone(candidate));
}

function prepareMaeDefinitionWork3FamilyPackageRegistration(input) {
  const contractCode = MAE_WORK3_REGISTRATION_CODES.CONTRACT;
  if (!maeWork3HasOrderedKeys(input, MAE_WORK3_REGISTRATION_INPUT_KEYS)) {
    fail(contractCode, 'MAE Work3 family package registration input drift.');
  }
  const evidence = input.maeDefinitionWork3FamilyPackageRegistrationEvidence;
  const authorityEnvelope = maeWork3ValidatePinnedEnvelope(
    evidence.work3MaeDefinitionRegistrationSuccessorAuthority,
    maeWork3PhysicalBinding(
      MAE_WORK3_REGISTRATION_AUTHORITY_BYTES,
      MAE_WORK3_REGISTRATION_AUTHORITY_PATH,
      MAE_WORK3_REGISTRATION_AUTHORITY_ID,
      'work3_mae_definition_registration_successor_authority_id',
      MAE_WORK3_REGISTRATION_AUTHORITY_SCHEMA,
      MAE_WORK3_REGISTRATION_AUTHORITY_SHA256,
    ),
    'work3_mae_definition_registration_successor_authority_id',
    MAE_WORK3_REGISTRATION_CODES.AUTHORITY,
    'MAE Work3 registration successor authority',
  );
  maeWork3ValidatePhase4ReviewInput(input.maeDefinitionPhase4ReviewInput);
  const sealReceiptRecord = maeWork3ValidateSealReceiptEnvelope(
    evidence.familyPackageSealReceipt,
  );

  const sealInput = {
    maeDefinitionWork3FamilyPackageSealEvidence: {
      work3MaeDefinitionBenInventorySessionSuccessorAuthority:
        evidence.work3MaeDefinitionBenInventorySessionSuccessorAuthority,
      work3MaeDefinitionFamilyPackageSealSuccessorAuthority:
        evidence.work3MaeDefinitionFamilyPackageSealSuccessorAuthority,
      inventoryReviewPacketDraft: evidence.inventoryReviewPacketDraft,
      benAuthoredInventoryDisposition: evidence.benAuthoredInventoryDisposition,
      benInventorySessionReceipt: evidence.benInventorySessionReceipt,
    },
    maeDefinitionPhase4ReviewInput: input.maeDefinitionPhase4ReviewInput,
  };
  let sealCandidate;
  try {
    sealCandidate = prepareMaeDefinitionWork3FamilyPackageSeal(sealInput);
  } catch (error) {
    fail(
      MAE_WORK3_REGISTRATION_CODES.SEAL,
      'MAE Work3 family package registration seal derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }
  if (sealCandidate.family_package_seal_id !== sealReceiptRecord.family_package_seal_id) {
    fail(
      MAE_WORK3_REGISTRATION_CODES.SEAL_RECEIPT,
      'MAE Work3 family package registration seal receipt identity drift.',
    );
  }

  let phase4Review;
  try {
    phase4Review = prepareMaeDefinitionFamilyProfilePackageReview(
      input.maeDefinitionPhase4ReviewInput,
    );
  } catch (error) {
    fail(
      MAE_WORK3_REGISTRATION_CODES.OUTPUT,
      'MAE Work3 family package registration Phase4 derivation failed.',
      { cause_code: typeof error.code === 'string' ? error.code : null },
    );
  }

  const dispositionByKey = new Map(
    evidence.benAuthoredInventoryDisposition.record.profile_dispositions.map(
      (row) => [row.proposed_profile_key, row],
    ),
  );
  const registeredProfileIdentities = [...phase4Review.proposed_profiles]
    .sort((left, right) => compareStrings(
      left.proposed_profile_key,
      right.proposed_profile_key,
    ))
    .map((profile) => {
      const disposition = dispositionByKey.get(profile.proposed_profile_key);
      if (!disposition || disposition.disposition !== 'APPROVE') {
        fail(
          MAE_WORK3_REGISTRATION_CODES.OUTPUT,
          'MAE Work3 family package registration disposition row drift.',
        );
      }
      const profileId = maeWork3RegistrationProfileId(
        profile.proposed_profile_key,
        profile.package_profile_key,
      );
      return {
        profile_id: profileId,
        proposed_profile_key: profile.proposed_profile_key,
        package_profile_key: profile.package_profile_key,
        disposition: disposition.disposition,
        review_flags_acknowledged: clone(disposition.review_flags_acknowledged),
      };
    });
  const profileIdentityIds = registeredProfileIdentities
    .map((row) => row.profile_id)
    .sort(compareStrings);
  const familyProfilePackageId = contentId(
    MAE_WORK3_FAMILY_PROFILE_PACKAGE_IDENTITY_SCHEMA,
    {
      family_key: 'MAE_DEFINITION',
      profile_identity_ids: profileIdentityIds,
      family_package_seal_receipt_id:
        sealReceiptRecord.mae_definition_family_package_seal_receipt_id,
    },
  );
  const inventoryFingerprint = sha256Hex(canonicalJson({
    inventory_disposition_id: sealReceiptRecord.disposition_binding.record_id,
    profile_identity_ids: profileIdentityIds,
  }));

  const authority = authorityEnvelope.record;
  const contract = authority.schema_review_candidate_contract;
  const unsigned = {
    candidate_state: contract.candidate_state,
    authority_binding: maeWork3AuthorityBinding(authorityEnvelope),
    family_package_seal_receipt_binding: {
      path: MAE_WORK3_REGISTRATION_SEAL_RECEIPT_PATH,
      mae_definition_family_package_seal_receipt_id:
        sealReceiptRecord.mae_definition_family_package_seal_receipt_id,
      family_package_seal_id: sealReceiptRecord.family_package_seal_id,
    },
    family_package_seal_reference: {
      family_package_seal_id: sealCandidate.family_package_seal_id,
      candidate_state: sealCandidate.candidate_state,
    },
    family_profile_package_identity: {
      family_profile_package_id: familyProfilePackageId,
      family_key: 'MAE_DEFINITION',
      profile_identity_ids: profileIdentityIds,
      inventory_disposition_id: MAE_WORK3_BEN_INVENTORY_DISPOSITION_ID,
      family_package_seal_receipt_id:
        sealReceiptRecord.mae_definition_family_package_seal_receipt_id,
    },
    registered_profile_identities: registeredProfileIdentities,
    inventory_fingerprint: inventoryFingerprint,
    review_accounting: clone(contract.review_accounting_exact_values),
    withheld_work3_fields: clone(MAE_WORK3_WITHHELD_FIELDS),
    next_governance_stop: {
      state: 'STOP_AFTER_FAMILY_PACKAGE_REGISTRATION_BEFORE_ACTIVATION',
      package_registration_state: 'RECORDED',
      activation_permitted: false,
    },
    zero_effect_boundary: clone(authority.zero_effect_boundary),
  };
  const candidate = {
    schema_version: MAE_WORK3_REGISTRATION_CANDIDATE_SCHEMA,
    family_package_registration_id: contentId(
      MAE_WORK3_REGISTRATION_CANDIDATE_SCHEMA,
      {
        schema_version: MAE_WORK3_REGISTRATION_CANDIDATE_SCHEMA,
        ...unsigned,
      },
    ),
    ...unsigned,
  };
  if (
    !exactKeys(candidate, MAE_WORK3_REGISTRATION_CANDIDATE_KEYS) ||
    candidate.registered_profile_identities.length !== 4 ||
    candidate.review_accounting.work3_identity_count !== 5 ||
    candidate.review_accounting.profile_identity_count !== 4
  ) {
    fail(MAE_WORK3_REGISTRATION_CODES.OUTPUT, 'MAE Work3 family package registration output drift.');
  }
  return deepFreeze(clone(candidate));
}
// === end MAE_DEFINITION family authoring ===

// === DNO_INDEMNIFICATION family authoring (merged from m7-v2-dno-indemnification-authoring.js) ===

// DNO family helpers (reuse spine primitives)
function dnoIsObject(value) {
  return isPlainObject(value);
}

function dnoSameValue(left, right) {
  return equalCanonical(left, right);
}

function dnoExactKeysOrFail(value, expectedKeys, code, label) {
  if (!exactKeys(value, expectedKeys)) {
    fail(code, `${label} has unexpected keys.`);
  }
}

function dnoSortedUnique(values) {
  return [...new Set(values)].sort(compareStrings);
}

function dnoValidateBoundSource(source, expectedBinding, code, label) {
  validateEnvelopeShape(source, code, label);
  dnoExactKeysOrFail(
    source.binding,
    Object.keys(expectedBinding),
    code,
    `${label} binding`,
  );
  if (!dnoSameValue(source.binding, expectedBinding)) {
    fail(code, `${label} binding does not match the Phase2 authority.`);
  }
  validateBoundRecord(source, code, label);
}

