function guarantyWork3ValidatePinnedEnvelope(envelope, expected, label) {
  validateEnvelopeShape(envelope, GUARANTY_WORK3_CODES.AUTHORITY, label);
  if (!guarantySameValue(envelope.binding, expected)) {
    fail(GUARANTY_WORK3_CODES.AUTHORITY, `${label} binding drift.`);
  }
  validateBoundRecord(envelope, GUARANTY_WORK3_CODES.AUTHORITY, label);
  const unsigned = clone(envelope.record);
  delete unsigned[expected.record_id_field];
  if (expected.record_id_field === 'inventory_disposition_id') {
    delete unsigned.session_receipt_id;
  }
  if (contentId(envelope.record.schema_version, unsigned) !== expected.record_id) {
    fail(GUARANTY_WORK3_CODES.AUTHORITY, `${label} self identity drift.`);
  }
  return deepFreeze(clone(envelope));
}

function guarantyWork3ValidateInput(input, outerKeys, evidenceKey, evidenceKeys) {
  guarantyExactKeysOrFail(input, outerKeys, GUARANTY_WORK3_CODES.CONTRACT, 'Guaranty Work3 input');
  const evidence = input[evidenceKey];
  guarantyExactKeysOrFail(
    evidence,
    evidenceKeys,
    GUARANTY_WORK3_CODES.CONTRACT,
    'Guaranty Work3 evidence bundle',
  );
  for (const key of evidenceKeys) {
    if (!guarantyIsObject(evidence[key]) || !guarantyIsObject(evidence[key].binding) || !guarantyIsObject(evidence[key].record)) {
      fail(GUARANTY_WORK3_CODES.CONTRACT, `Guaranty Work3 ${key} envelope drift.`);
    }
  }
  return evidence;
}

function guarantyWork3Phase4(input) {
  try {
    return prepareGuarantyFinancingPartyFamilyProfilePackageReview(input);
  } catch (error) {
    fail(GUARANTY_WORK3_CODES.INVENTORY, 'Guaranty Work3 Phase4 review derivation failed.', {
      cause_code: typeof error.code === 'string' ? error.code : null,
    });
  }
}

function validateGuarantyFinancingPartyUnapprovedInventoryReviewEvidence(evidence) {
  if (
    !guarantyIsObject(evidence)
    || evidence.profile_approval_state !== 'UNAPPROVED'
    || evidence.profile_count !== 5
    || evidence.complete_profile_count !== 5
    || evidence.incomplete_profile_count !== 0
    || !Array.isArray(evidence.proposed_profiles)
    || evidence.proposed_profiles.length !== 5
    || !Array.isArray(evidence.retained_source_gaps)
    || evidence.retained_source_gaps.length !== 0
    || guarantySortedUnique(evidence.proposed_profiles.map((profile) => profile.proposed_profile_key)).length !== 5
  ) {
    fail(GUARANTY_WORK3_CODES.INVENTORY, 'Guaranty unapproved inventory review evidence census drift.');
  }
  return deepFreeze({
    schema_version: 'M7_V2_GUARANTY_FINANCING_PARTY_UNAPPROVED_INVENTORY_REVIEW_VALIDATOR_ACCEPTANCE/V1',
    status: 'PASS',
    profile_count: 5,
    complete_profile_count: 5,
    incomplete_profile_count: 0,
    retained_source_gap_count: 0,
  });
}

