function guarantyWork3ValidatePacket(envelope) {
  guarantyWork3ValidatePinnedEnvelope(envelope, GUARANTY_WORK3_PACKET_BINDING, 'Guaranty inventory packet');
  const record = envelope.record;
  if (
    record.profile_count !== 5
    || record.complete_profile_count !== 5
    || record.incomplete_profile_count !== 0
    || record.retained_source_gap_count !== 0
    || !Array.isArray(record.profile_review_items)
    || record.profile_review_items.length !== 5
    || record.profile_review_items.filter((item) => item.review_flags.includes(
      'LEGAL_GROUPING_REVIEW_REQUIRED',
    )).length !== 5
  ) fail(GUARANTY_WORK3_CODES.INVENTORY, 'Guaranty inventory packet census drift.');
  return record;
}

function guarantyWork3ValidateDisposition(envelope) {
  guarantyWork3ValidatePinnedEnvelope(envelope, GUARANTY_WORK3_DISPOSITION_BINDING, 'Guaranty Ben disposition');
  const record = envelope.record;
  const rows = record.profile_dispositions;
  const summary = record.session_summary;
  if (
    record.reviewer !== 'BEN_GOODCHILD'
    || record.default_disposition_applied !== true
    || record.packet_digest !== GUARANTY_WORK3_PACKET_BINDING.sha256
    || record.ben_rulings_digest !== GUARANTY_WORK3_RULINGS_BINDING.sha256
    || !Array.isArray(rows)
    || rows.length !== 5
    || rows.filter((row) => row.disposition === 'APPROVE').length !== 5
    || summary.approved_count !== 5
    || summary.hold_count !== 0
    || summary.legal_grouping_review_pending_count !== 5
    || summary.taxonomy_expansion_acknowledged !== true
  ) fail(GUARANTY_WORK3_CODES.DISPOSITION, 'Guaranty Ben inventory disposition drift.');
  return record;
}

